				Expect(err).To(BeNil())
				Expect(pager).ToNot(BeNil())

				var allResults []vpcv1.VPC
				for pager.HasNext() {
					nextPage, err := pager.GetNext()
					Expect(err).To(BeNil())
					Expect(nextPage).ToNot(BeNil())
					allResults = append(allResults, nextPage...)
				}
				Expect(len(allResults)).To(Equal(2))
