	Describe(`CreateVPC(createVPCOptions *CreateVPCOptions) - Operation response error`, func() {
		version := "2024-06-23"
		createVPCPath := "/vpcs"
		Context(`Using mock server endpoint with invalid JSON response`, func() {
			BeforeEach(func() {
				testServer = httptest.NewServer(http.HandlerFunc(func(res http.ResponseWriter, req *http.Request) {
					defer GinkgoRecover()

					// Verify the contents of the request
					Expect(req.URL.EscapedPath()).To(Equal(createVPCPath))
					Expect(req.Method).To(Equal("POST"))
					Expect(req.URL.Query()["version"]).To(Equal([]string{"2024-06-23"}))
					Expect(req.URL.Query()["generation"]).To(Equal([]string{fmt.Sprint(int64(2))}))
					res.Header().Set("Content-type", "application/json")
					res.WriteHeader(201)
					fmt.Fprint(res, `} this is not valid json {`)
				}))
			})
			It(`Invoke CreateVPC with error: Operation response processing error`, func() {
				vpcService, serviceErr := vpcv1.NewVpcV1(&vpcv1.VpcV1Options{
					URL:           testServer.URL,
					Authenticator: &core.NoAuthAuthenticator{},
					Version: core.StringPtr(version),
				})
				Expect(serviceErr).To(BeNil())
				Expect(vpcService).ToNot(BeNil())

				// Construct an instance of the ZoneIdentityByName model
				zoneIdentityModel := new(vpcv1.ZoneIdentityByName)
				zoneIdentityModel.Name = core.StringPtr("us-south-1")

				// Construct an instance of the DnsServerPrototype model
				dnsServerPrototypeModel := new(vpcv1.DnsServerPrototype)
				dnsServerPrototypeModel.Address = core.StringPtr("192.168.3.4")
				dnsServerPrototypeModel.ZoneAffinity = zoneIdentityModel

				// Construct an instance of the VpcdnsResolverPrototypeVpcdnsResolverTypeManualPrototype model
				vpcdnsResolverPrototypeModel := new(vpcv1.VpcdnsResolverPrototypeVpcdnsResolverTypeManualPrototype)
				vpcdnsResolverPrototypeModel.ManualServers = []vpcv1.DnsServerPrototype{*dnsServerPrototypeModel}
				vpcdnsResolverPrototypeModel.Type = core.StringPtr("manual")

				// Construct an instance of the VpcdnsPrototype model
				vpcdnsPrototypeModel := new(vpcv1.VpcdnsPrototype)
				vpcdnsPrototypeModel.EnableHub = core.BoolPtr(true)
				vpcdnsPrototypeModel.Resolver = vpcdnsResolverPrototypeModel

				// Construct an instance of the ResourceGroupIdentityByID model
				resourceGroupIdentityModel := new(vpcv1.ResourceGroupIdentityByID)
				resourceGroupIdentityModel.ID = core.StringPtr("fee82deba12e4c0fb69c3b09d1f12345")

				// Construct an instance of the CreateVPCOptions model
				createVPCOptionsModel := new(vpcv1.CreateVPCOptions)
				createVPCOptionsModel.AddressPrefixManagement = core.StringPtr("auto")
				createVPCOptionsModel.ClassicAccess = core.BoolPtr(true)
				createVPCOptionsModel.Dns = vpcdnsPrototypeModel
				createVPCOptionsModel.Name = core.StringPtr("my-vpc")
				createVPCOptionsModel.ResourceGroup = resourceGroupIdentityModel
				createVPCOptionsModel.Headers = map[string]string{"x-custom-header": "x-custom-value"}
				// Expect response parsing to fail since we are receiving a text/plain response
				result, response, operationErr := vpcService.CreateVPC(createVPCOptionsModel)
				Expect(operationErr).ToNot(BeNil())
				Expect(response).ToNot(BeNil())
				Expect(result).To(BeNil())

				// Enable retries and test again
				vpcService.EnableRetries(0, 0)
				result, response, operationErr = vpcService.CreateVPC(createVPCOptionsModel)
				Expect(operationErr).ToNot(BeNil())
				Expect(response).ToNot(BeNil())
				Expect(result).To(BeNil())
			})
			AfterEach(func() {
				testServer.Close()
			})
		})
	})
